            blocked[i] = fr.nextInt() == 1;
        }
        if (blocked[0] || blocked[total - 1]) {
            System.out.println(-1);
            return;
        }
        int[] dist = new int[total];
        Arrays.fill(dist, -1);
        int[] queue = new int[total];
        int head = 0;
        int tail = 0;
        queue[tail++] = 0;
        dist[0] = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (head < tail) {
            int cell = queue[head++];
            int cr = cell / c;
            int cc = cell % c;
            for (int d = 0; d < 4; d++) {
                int nr = cr + dr[d];
                int nc = cc + dc[d];
                if (nr >= 0 && nr < r && nc >= 0 && nc < c) {
                    int next = nr * c + nc;
                    if (!blocked[next] && dist[next] == -1) {
                        dist[next] = dist[cell] + 1;
                        queue[tail++] = next;
                    }
                }
            }
        }
        System.out.println(dist[total - 1]);
    }
}

