import java.io.*;
import java.util.*;

public class Main {
    static int[] start;
    static int[] adj;

    static void buildUndirected(int n, int[] eu, int[] ev) {
        int m = eu.length;
        start = new int[n + 2];
        for (int i = 0; i < m; i++) {
            start[eu[i] + 1]++;
            start[ev[i] + 1]++;
        }
        for (int i = 1; i <= n + 1; i++) {
            start[i] += start[i - 1];
        }
        adj = new int[2 * m];
        int[] pos = Arrays.copyOf(start, n + 2);
        for (int i = 0; i < m; i++) {
            adj[pos[eu[i]]++] = ev[i];
            adj[pos[ev[i]]++] = eu[i];
        }
        for (int v = 1; v <= n; v++) {
            Arrays.sort(adj, start[v], start[v + 1]);
        }
    }

    static void readUndirected(FastReader fr, int n, int m) throws IOException {
        int[] eu = new int[m];
        int[] ev = new int[m];
        for (int i = 0; i < m; i++) {
            eu[i] = fr.nextInt();
            ev[i] = fr.nextInt();
        }
        buildUndirected(n, eu, ev);
    }

    static int[] disc;
    static int[] low;
    static boolean[] isCut;
    static int timer;

    static void dfs(int u, int parent) {
        disc[u] = low[u] = ++timer;
        int children = 0;
        for (int i = start[u]; i < start[u + 1]; i++) {
            int v = adj[i];
            if (v == parent) {
                continue;
            }
            if (disc[v] == 0) {
                children++;
                dfs(v, u);
                low[u] = Math.min(low[u], low[v]);
                if (parent != 0 && low[v] >= disc[u]) {
                    isCut[u] = true;
                }
            } else {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
        if (parent == 0 && children > 1) {
            isCut[u] = true; // a DFS root is a cut vertex only if it has 2+ tree children
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int m = fr.nextInt();
        readUndirected(fr, n, m);
        disc = new int[n + 1];
        low = new int[n + 1];
        isCut = new boolean[n + 1];
        for (int v = 1; v <= n; v++) {
            if (disc[v] == 0) {
                dfs(v, 0);
            }
        }
        StringBuilder list = new StringBuilder();
        int count = 0;
        for (int v = 1; v <= n; v++) {
            if (isCut[v]) {
                count++;
                if (list.length() > 0) {
                    list.append(' ');
                }
                list.append(v);
            }
        }
        System.out.println(count);
        System.out.println(list);
    }
}

